static bool     cfg_dirty;
static uint32_t last_change_ms;

void config_set_rate(uint16_t rate) {
    if (cfg.rate == rate) {
        return;               // nothing changed
    }
    cfg.rate = rate;
    cfg_dirty = true;
    last_change_ms = now_ms();
}

void config_poll(void) {      // main loop
    if (cfg_dirty && (uint32_t)(now_ms() - last_change_ms) > 5000) {
        flash_write_cfg(&cfg);
        cfg_dirty = false;
    }
}

